function toast(msg, type = 'success', duration = 2200) {
  const c = $('#toast-container');
  const t = document.createElement('div');
  t.className = `toast ${type}`;
  t.innerHTML = `<i class="fas fa-${type === 'success' ? 'check-circle' : 'exclamation-circle'}"></i><span>${msg}</span>`;
  c.appendChild(t);
  setTimeout(() => t.remove(), duration);
}

function showModal(title, bodyHTML, modalClass = '', { pauseMedia = true } = {}) {
  stopProfileNoteAudio();
  const photoEditAudio = $('#edit-photo-song-audio');
  if (photoEditAudio) {
    photoEditAudio.pause();
    photoEditAudio.removeAttribute('src');
    photoEditAudio.load();
  }
  if (pauseMedia && activePlaylistPreviewAudio) {
    activePlaylistPreviewAudio.pause();
    untrackMediaAudio(activePlaylistPreviewAudio);
    activePlaylistPreviewAudio = null;
    activePlaylistPreviewButton = null;
  }
  if (pauseMedia) managedMediaAudio.forEach(audio => audio.pause());
  $('#modal-title').textContent = title;
  $('#modal-body').innerHTML = bodyHTML;
  $('#modal').classList.remove('social-compose-modal', 'newspaper-editor-modal', 'dm-first-theme-modal', 'register-avatar-viewer-modal', 'dm-photo-editor-modal', 'song-editor-modal', 'profile-note-viewer-modal', 'profile-badges-modal', 'red-verification-modal', 'photo-edit-modal', 'photo-description-modal', 'story-visibility-confirm-modal', 'playlist-picker-modal');
  if (modalClass) $('#modal').classList.add(modalClass);
  $('#modal-overlay').classList.remove('hidden');
}

function hideModal({ resumeReals = true } = {}) {
  stopProfileNoteAudio();
  const photoEditAudio = $('#edit-photo-song-audio');
  if (photoEditAudio) {
    photoEditAudio.pause();
    photoEditAudio.removeAttribute('src');
    photoEditAudio.load();
  }
  if (storyComposerAudio) { storyComposerAudio.pause(); untrackMediaAudio(storyComposerAudio); storyComposerAudio.src = ''; storyComposerAudio = null; }
  if (activeStoryAudio) { activeStoryAudio.pause(); untrackMediaAudio(activeStoryAudio); activeStoryAudio.src = ''; activeStoryAudio = null; }
  if (activeRealsAudio) { activeRealsAudio.pause(); untrackMediaAudio(activeRealsAudio); activeRealsAudio.src = ''; activeRealsAudio = null; }
  if (resumeReals) {
    window.__realsResumeVideo?.();
    window.__realsResumeVideo = null;
  }
  if (activeVideoPreviewObjectUrl) {
    URL.revokeObjectURL(activeVideoPreviewObjectUrl);
    activeVideoPreviewObjectUrl = null;
  }
  $('#modal-overlay').classList.add('hidden');
  $('#modal-overlay').classList.remove('story-fullscreen-overlay');
  $('#modal')?.classList.remove('social-compose-modal', 'newspaper-editor-modal', 'dm-first-theme-modal', 'register-avatar-viewer-modal', 'dm-photo-editor-modal', 'profile-note-viewer-modal', 'red-verification-modal', 'photo-edit-modal', 'photo-description-modal', 'story-visibility-confirm-modal');
}

function descriptionPreviewHTML(description, className, maxLength = 150) {
  const text = String(description || '');
  if (!text) return '';
  const preview = text.replace(/\s+/g, ' ').trim();
  if (preview.length <= maxLength) return `<div class="${className}">${escHtml(text)}</div>`;
  return `<button type="button" class="${className} description-preview" data-full-description="${escHtml(text)}" aria-label="Açıklamanın tamamını görüntüle">${escHtml(preview.slice(0, maxLength).trimEnd())}... <span>Devamını gör</span></button>`;
}

function formatCount(value) {
  const count = Number(typeof value === 'string' ? value.replace(/[^\d]/g, '') : value);
  return Number.isFinite(count) && count > 0 ? Math.floor(count).toLocaleString('tr-TR') : '0';
}

function showDescriptionModal(text, sourceElement = null) {
  const realsVideo = sourceElement?.closest('.reals-item')?.querySelector('video');
  if (realsVideo) {
    const wasPlaying = !realsVideo.paused;
    if (wasPlaying) realsVideo.pause();
    window.__realsResumeVideo = () => {
      if (wasPlaying && location.pathname === '/reals') realsVideo.play().catch(() => {});
    };
  }
  showModal('Açıklama', `<div class="description-modal">
    <div class="description-modal-content">${escHtml(text)}</div>
    <button type="button" class="btn btn-primary description-modal-close" id="description-modal-close">Kapat</button>
  </div>`, sourceElement?.closest('.photo-card') ? 'photo-description-modal' : '');
  document.getElementById('description-modal-close')?.addEventListener('click', hideModal);
}

function showImagePreviewModal(url, title = 'Görsel önizlemesi') {
  if (!url) return;
  showModal(title, `<div class="media-preview-modal"><div><img src="${escHtml(url)}" alt="${escHtml(title)}" /></div></div>`);
}

