// ===== IÇERIK RENDER (hashtag + mention) =====
function renderContent(text) {
  if (!text) return '';
  // XSS güvenli: önce escape, sonra pattern'lere dönüştür
  let safe = String(text)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  const links = [];
  safe = safe.replace(/(?:https?:\/\/|www\.)[^\s<]+/gi, match => {
    const trailing = match.match(/[.,!?;:)]+$/)?.[0] || '';
    const url = trailing ? match.slice(0, -trailing.length) : match;
    const placeholder = `__CIGCIG_LINK_${links.length}__`;
    const href = normalizeExternalUrl(url);
    links.push({ placeholder, url, href, imageHref: siteImageUrl(href), isImage: /\.(?:png|jpe?g|gif|webp|avif|bmp)(?:[?#].*)?$/i.test(url) });
    return placeholder + trailing;
  });
  safe = safe;
  links.forEach(({ placeholder, url, href, imageHref, isImage }) => {
    safe = safe.replaceAll(placeholder, isImage
      ? `<a href="${imageHref}" target="_blank" rel="noopener noreferrer" class="inline-image-link"><img src="${imageHref}" alt="Paylaşılan görsel" loading="lazy" /></a>`
      : `<a href="${href}" target="_blank" rel="noopener noreferrer" class="inline-link" data-preview-url="${href}">${url}</a>`);
  });
  return safe;
}

async function enhanceLinkPreviews(root = document) {
  const links = [...root.querySelectorAll?.('[data-preview-url]:not([data-preview-bound])') || []];
  links.forEach(link => link.dataset.previewBound = '1');
  await Promise.all(links.map(async link => {
    try {
      const rawUrl = String(link.dataset.previewUrl || link.href || '').trim();
      if (!rawUrl) return;
      const preview = await api('/link-preview?url=' + encodeURIComponent(rawUrl));
      if (!preview || (!preview.title && !preview.image && !preview.site && !preview.url)) return;
      if (preview.is_image) {
        const imageLink = document.createElement('a');
        imageLink.className = 'inline-image-link';
        imageLink.href = siteImageUrl(preview.url || rawUrl);
        imageLink.target = '_blank';
        imageLink.rel = 'noopener noreferrer';
        imageLink.innerHTML = `<img src="${escHtml(siteImageUrl(preview.image || preview.url || rawUrl))}" alt="Paylaşılan görsel" loading="lazy" />`;
        link.replaceWith(imageLink);
        return;
      }
      const card = document.createElement('a');
      card.className = 'link-preview-card';
      card.href = preview.url || rawUrl;
      card.target = '_blank';
      card.rel = 'noopener noreferrer';
      card.dataset.previewUrl = rawUrl;
      const imageMarkup = preview.image
        ? `<img src="${escHtml(preview.image)}" alt="" loading="lazy" class="link-preview-image" />`
        : `<span class="link-preview-icon"><i class="fas fa-globe"></i></span>`;
      const title = preview.title || preview.site || 'Bağlantı';
      const desc = preview.description || '';
      const site = preview.site || '';
      card.innerHTML = `${imageMarkup}<span class="link-preview-copy"><strong>${escHtml(title)}</strong>${desc ? `<small>${escHtml(desc)}</small>` : ''}<em>${escHtml(site)}</em></span>`;
      link.replaceWith(card);
    } catch (e) {
      // Aynı içerik hattında başarısız önizlemeler, bağlantıyı kırpmadan metin olarak kalır.
    }
  }));
}

function navigate(path, push = true) {
  closeMobileMenu();
  closeMobileCreateMenu();
  $('#new-dropdown')?.classList.add('hidden');
  if (push) history.pushState({}, '', path);
  // path içindeki query string'i renderRoute'a geçir
  renderRoute(path);
}

function createForgotPasswordRoute() {
  const alphabet = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
  const values = new Uint32Array(24);
  if (window.crypto?.getRandomValues) window.crypto.getRandomValues(values);
  else values.forEach((_, index) => { values[index] = Math.floor(Math.random() * 0xffffffff); });
  return '/' + Array.from(values, value => alphabet[value % alphabet.length]).join('');
}

function isForgotPasswordRoute(path) {
  return /^\/[a-zA-Z0-9]{24}$/.test(path);
}

function isPublicGuestRoute(path) {
  const normalizedPath = path.replace(/\/+$/, '') || '/';
  return normalizedPath === '/giris'
    || normalizedPath === '/kayit'
    || normalizedPath === '/muzikler'
    || normalizedPath === '/kitaplar'
    || normalizedPath === '/forum'
    || normalizedPath === '/konular'
    || /^\/reals(?:\/[^/]+)?$/.test(normalizedPath)
    || /^\/(?:muzik|forum)\/[^/]+(?:\/.*)?$/.test(normalizedPath)
    || /^\/kitap\/[^/]+(?:\/sayfa\/[^/]+)?$/.test(normalizedPath)
    || isForgotPasswordRoute(normalizedPath);
}

window.addEventListener('popstate', () => {
  closeMobileCreateMenu();
  renderRoute(location.pathname + location.search);
});

document.addEventListener('click', e => {
  const a = e.target.closest('[data-link]');
  if (a && a.tagName === 'A') {
    e.preventDefault();
    if (a.id === 'mbb-music' && !currentAudio?.dataset?.listeningTrackId && currentAudio?.musicResume?.type === 'song' && currentAudio.musicResume.slug) {
      return navigate('/muzik/' + encodeURIComponent(currentAudio.musicResume.slug));
    }
    navigate(a.getAttribute('href'));
  }
});

document.addEventListener('pointerover', event => {
  if (event.pointerType === 'touch') return;
  const link = event.target.closest('[data-link]');
  if (link instanceof HTMLAnchorElement) prefetchRouteData(link.href);
});

document.addEventListener('focusin', event => {
  const link = event.target.closest('[data-link]');
  if (link instanceof HTMLAnchorElement) prefetchRouteData(link.href);
});

let previousRenderedRoutePath = null;
let dmSuggestionsReturningFromProfile = false;

function renderRoute(fullPath) {
  window.__profileMenuCleanup?.();
  clearStoryRoutePlayback();
  // Sayfa değişiminde fotoğraf ses kontrolünü kaldır
  document.getElementById('photo-audio-control')?.remove();
  photoAudioObserver?.disconnect();
  activePhotoAudio?.pause();
  untrackMediaAudio(activePhotoAudio);
  activePhotoAudio = null;
  photoAudioObserver = null;
  if (activeStoryAudio) { activeStoryAudio.pause(); untrackMediaAudio(activeStoryAudio); activeStoryAudio.src = ''; activeStoryAudio = null; }
  if (activeRealsAudio) { activeRealsAudio.pause(); untrackMediaAudio(activeRealsAudio); activeRealsAudio.src = ''; activeRealsAudio = null; }

  // Query string'i ayır
  const [path, queryStr] = fullPath.split('?');
  const previousPath = previousRenderedRoutePath;
  let rotateDmSuggestions = false;
  const wasOnReals = document.body.classList.contains('reals-page');
  const isGoingToReals = path === '/reals' || path.startsWith('/reals/');
  if (wasOnReals && !isGoingToReals && window.__realsVideoResizeHandler) {
    window.removeEventListener('resize', window.__realsVideoResizeHandler);
    window.__realsVideoResizeHandler = null;
  }
  if (wasOnReals && !isGoingToReals && window.__realsKeydownHandler) {
    window.removeEventListener('keydown', window.__realsKeydownHandler);
    window.__realsKeydownHandler = null;
  }
  if (loginRequiredEnabled && !currentUser && !isPublicGuestRoute(path)) {
    return navigate('/giris', false);
  }
  const wasInMessages = previousPath === '/mesajlar' || previousPath?.startsWith('/mesajlar/');
  const isInMessages = path === '/mesajlar' || path.startsWith('/mesajlar/');
  if (wasInMessages && path.startsWith('/profil/')) dmSuggestionsReturningFromProfile = true;
  const returnedFromProfile = isInMessages && previousPath?.startsWith('/profil/') && dmSuggestionsReturningFromProfile;
  if (returnedFromProfile) dmSuggestionsReturningFromProfile = false;
  if (path === '/mesajlar' && !wasInMessages) {
    if (!returnedFromProfile && currentUser?.id) {
      try {
        const visitKey = `dm_suggestions_visits:${currentUser.id}`;
        const visits = (Number(sessionStorage.getItem(visitKey)) || 0) + 1;
        rotateDmSuggestions = visits >= 3;
        sessionStorage.setItem(visitKey, String(visits));
      } catch (error) {
        console.warn('Önerilen kişiler giriş sayısı kaydedilemedi.', error);
      }
    }
  } else if (!path.startsWith('/profil/') && !isInMessages) {
    dmSuggestionsReturningFromProfile = false;
  }
  previousRenderedRoutePath = path;
  document.body.classList.toggle('auth-route', path === '/giris' || path === '/kayit' || isForgotPasswordRoute(path));
  document.body.classList.toggle('forgot-password-route', isForgotPasswordRoute(path));
  const leavingSongDetail = !path.startsWith('/muzik/');
  const detailAudio = document.getElementById('detail-audio');
  if (leavingSongDetail && detailAudio && currentAudio === detailAudio && detailAudio.musicResume?.type === 'song') {
    const resume = detailAudio.musicResume;
    const queueState = getMusicQueueState(resume.song);
    openMiniPlayer(resume.audio_url, resume.slug, resume.song, queueState.queue, queueState.index, {
      startAt: detailAudio.currentTime,
      autoplay: !detailAudio.paused,
      countPlay: false
    });
  }
  if (isGoingToReals && !wasOnReals) {
    suspendMusicForReals();
  } else if (!isGoingToReals && wasOnReals) {
    resumeMusicAfterReals();
  }
  document.body.classList.toggle('song-detail-route', path.startsWith('/muzik/'));
  const isDmChatRoute = path.startsWith('/mesajlar/') && path.split('/').filter(Boolean).length > 1;
  const isGroupChatRoute = path.startsWith('/grup/') && path.split('/').filter(Boolean).length > 1;
  document.body.classList.toggle('story-page', path.startsWith('/hikaye/'));
  document.body.classList.toggle('dm-chat-route', isDmChatRoute);
  document.body.classList.toggle('group-chat-route', isGroupChatRoute);
  document.body.classList.toggle('messages-page', path === '/mesajlar');
  document.body.classList.toggle('reals-page', path === '/reals' || path.startsWith('/reals/'));
  const siteNavbar = document.getElementById('navbar');
  if (siteNavbar) siteNavbar.hidden = path === '/reals' || path.startsWith('/reals/');
  document.body.classList.toggle('home-page', path === '/');
  document.body.classList.toggle('music-list-page', path === '/muzikler');
  updateNavActive(path);
  // Mesaj başlığı/sohbet ekranında footer gizlenir; genel mesaj listesi sabit kalır.
  const siteFooter = document.getElementById('site-footer');
  if (siteFooter) {
    siteFooter.style.display = (isDmChatRoute || path === '/reals') ? 'none' : '';
  }
  const app = $('#app');
  const segs = path.split('/').filter(Boolean);

  if (path === '/') {
    return renderHome(app);
  }
  if (path === '/gazeteler') return renderNewspaperList(app);
  if (path.startsWith('/gazete/')) return renderNewspaperDetail(app, path.slice('/gazete/'.length));
  if (path === '/arama') return renderSearch(app, queryStr || '');
  if (path === '/forum' || path === '/konular') {
    // query string'i de geçir
    const qs = queryStr ? '?' + queryStr : '';
    return renderForumList(app, qs);
  }
  if (path === '/siirler') return renderPoemList(app);
  if (path.startsWith('/forum/')) {
    const slug = segs.slice(1).join('/');
    return renderForumDetail(app, slug);
  }
  if (path.startsWith('/siir/')) {
    const slug = segs.slice(1).join('/');
    return renderPoemDetail(app, slug);
  }
  if (path === '/kitaplar') return renderBookList(app);
  if (path.startsWith('/kitap/') && segs.length === 2) return renderBookDetail(app, segs[1]);
  if (path.startsWith('/kitap/') && segs.length === 4 && segs[2] === 'sayfa') return renderPageReader(app, segs[1], segs[3]);
  if (path === '/gruplar') return renderGroupList(app);
  if (path === '/fotograflar') return renderPhotos(app);
  if (path.startsWith('/hikaye/')) {
    if (!currentUser) return navigate('/giris', false);
    return renderStoryRoute(app, segs[1]);
  }
  if (path.startsWith('/grup/')) return renderGroupDetail(app, segs[1]);
  if (path === '/video' || path === '/videolar') return renderVideoList(app);
  if (path.startsWith('/video/')) return renderVideoDetail(app, segs[1]);
  if (path === '/reals' || path.startsWith('/reals/')) return renderRealsFeed(app, path.startsWith('/reals/') ? segs[1] : null);
  if (path.startsWith('/foto/')) return renderPhotoDetail(app, segs[1]);
  if (path.startsWith('/profil/')) return renderProfile(app, segs[1]);
  if (path === '/rozetler') return renderBadges(app);
  if (path === '/ayarlar') return renderSettings(app);
  if (path === '/giris') return renderLogin(app);
  if (path === '/kayit') return renderRegister(app);
  if (isForgotPasswordRoute(path)) return renderForgotPassword(app);
  if (path === '/mesajlar') return renderMessages(app, null, rotateDmSuggestions);
  if (path.startsWith('/mesajlar/')) return renderMessages(app, segs[1]);
  if (path === '/arkadaslar') return renderFriends(app);
  if (path === '/bildirimler') return renderNotifications(app);
  if (path === '/vmb') return renderVmb(app, 'home');
  if (path === '/vmb/dosyalar' || path === '/vmb/dosyalara') return renderVmb(app, 'files');
  if (path.startsWith('/vmb/dosyalar/') && segs.length === 3) return renderVmbFile(app, segs[2]);
  if (path.startsWith('/vmb/dosyalar/') && segs.length === 5 && segs[3] === 'klasor') return renderVmbFolder(app, segs[4]);
  if (path.startsWith('/vmb/dosyalar/') && segs.length === 7 && segs[3] === 'klasor' && segs[5] === 'sayfa') return renderVmbPageReader(app, segs[4], segs[6]);
  if (path === '/muzikler') return renderMusicList(app);
  if (path.startsWith('/muzik/')) return renderMusicDetail(app, segs[1]);
  if (path.startsWith('/ortak-dinleyis/')) return renderListeningRoom(app, segs[1]);
  if (path === '/reklampanel' || path.startsWith('/reklampanel/')) {
    const requestedAdId = segs[1] || new URLSearchParams(queryStr || '').get('id') || '';
    return renderAdPortal(app, requestedAdId);
  }
  if (path === '/artist-basvuru') return renderArtistApply(app);
  if (path === '/artist-panel') return renderArtistPanel(app);
  if (path === '/sarki-yukle') return renderShareSong(app);
  if (path === '/playlistlerim') return renderMyPlaylists(app);
  if (path.startsWith('/playlist/')) return renderPlaylistDetail(app, segs[1]);
    if (path === '/magaza') return renderStore(app);
  if (path === '/siparislerim') return renderMyOrders(app);
  renderNotFound(app);
}

function updateNavActive(path) {
  $$('.nav-link').forEach(l => {
    l.classList.toggle('active', l.getAttribute('href') === path || (l.getAttribute('href') !== '/' && path.startsWith(l.getAttribute('href'))));
  });
  updateMobileBottomBar(path);
}

// Reals feed basic viewer
function shuffleArray(arr) {
  const a = arr.slice();
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

function generateVideoPoster(file) {
  return new Promise((resolve, reject) => {
    const objectUrl = URL.createObjectURL(file);
    const video = document.createElement('video');
    video.preload = 'metadata';
    video.muted = true;
    video.playsInline = true;

    const cleanup = () => URL.revokeObjectURL(objectUrl);
    const createPoster = () => {
      const canvas = document.createElement('canvas');
      const scale = Math.min(1, 640 / Math.max(video.videoWidth, video.videoHeight, 1));
      canvas.width = Math.max(1, Math.round(video.videoWidth * scale));
      canvas.height = Math.max(1, Math.round(video.videoHeight * scale));
      const ctx = canvas.getContext('2d');
      if (!ctx) {
        cleanup();
        reject(new Error('Kapak görseli oluşturulamadı'));
        return;
      }
      ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
      canvas.toBlob(blob => {
        cleanup();
        if (!blob) return reject(new Error('Poster oluşturulamadı'));
        resolve(new File([blob], 'cigcig-kapak.jpg', { type: 'image/jpeg' }));
      }, 'image/jpeg', 0.78);
    };
    video.addEventListener('loadeddata', createPoster, { once: true });
    video.addEventListener('error', () => { cleanup(); reject(new Error('Video önizlemesi oluşturulamadı')); }, { once: true });
    video.src = objectUrl;
  });
}

