function searchExcerpt(text) {
  const value = String(text || '').replace(/\s+/g, ' ').trim();
  return value.length > 180 ? value.slice(0, 180) + '…' : value;
}

function searchResultHTML(result) {
  const [label, icon] = SEARCH_GROUPS[result.type] || ['İçerikler', 'fa-magnifying-glass'];
  return `<a class="search-result-card" href="${escHtml(result.route)}" data-link>
    <span class="search-result-icon"><i class="fas ${icon}"></i></span>
    <span class="search-result-copy">
      <strong>${escHtml(result.title || label)}</strong>
      ${result.excerpt ? `<small>${escHtml(searchExcerpt(result.excerpt))}</small>` : ''}
      <em>${escHtml(label)}${result.author ? ` · @${escHtml(result.author)}` : ''}</em>
    </span>
    ${result.avatar ? `<img src="${escHtml(result.avatar)}" class="search-result-avatar" alt="" />` : '<i class="fas fa-arrow-up-right-from-square search-result-arrow"></i>'}
  </a>`;
}

async function renderSearch(app, queryString = '') {
  const query = new URLSearchParams(queryString).get('q')?.trim() || '';
  document.title = (query ? `${query} · Arama` : 'Sitede Ara') + ' - ' + siteName;
  app.innerHTML = `<div class="container page search-page">
    <div class="page-header"><div class="page-title"><i class="fas fa-magnifying-glass" style="color:var(--accent-red)"></i> Sitede Ara</div></div>
    <form class="search-bar search-page-form" id="search-page-form">
      <i class="fas fa-search"></i><input id="search-page-input" type="search" value="${escHtml(query)}" placeholder="Başlık, içerik, yorum, müzik, kitap, profil veya grup ara..." autocomplete="off" />
      <button class="btn btn-primary btn-sm" type="submit">Ara</button>
    </form>
    <div id="search-page-results"></div>
  </div>`;
  const input = $('#search-page-input');
  $('#search-page-form')?.addEventListener('submit', event => {
    event.preventDefault();
    const value = input.value.trim();
    if (value) navigate('/arama?q=' + encodeURIComponent(value));
  });
  if (!query) {
    $('#search-page-results').innerHTML = '<div class="search-empty"><i class="fas fa-compass"></i><p>Herhangi bir başlık, içerik veya yorumu arayabilirsin.</p></div>';
    input.focus();
    return;
  }
  const resultEl = $('#search-page-results');
  resultEl.innerHTML = '<div class="loading-center"><div class="spinner"></div></div>';
  try {
    const results = await api('/search?q=' + encodeURIComponent(query) + '&limit=12');
    if (!results.length) {
      resultEl.innerHTML = `<div class="search-empty"><i class="fas fa-face-frown"></i><p><b>${escHtml(query)}</b> için sonuç bulunamadı.</p></div>`;
      return;
    }
    const groups = new Map();
    results.forEach(result => {
      const key = SEARCH_GROUPS[result.type]?.[0] || 'İçerikler';
      if (!groups.has(key)) groups.set(key, []);
      groups.get(key).push(result);
    });
    resultEl.innerHTML = `<div class="search-summary"><b>${results.length}</b> sonuç bulundu</div>` +
      Array.from(groups.entries()).map(([label, items]) => `<section class="search-results-section"><h2><i class="fas ${SEARCH_GROUPS[items[0].type]?.[1] || 'fa-magnifying-glass'}"></i>${escHtml(label)} <span>${items.length}</span></h2>${items.map(searchResultHTML).join('')}</section>`).join('');
  } catch (error) {
    resultEl.innerHTML = `<div class="search-empty search-error"><i class="fas fa-triangle-exclamation"></i><p>Arama şu anda yapılamıyor: ${escHtml(error.message)}</p></div>`;
  }
}

async function checkUnreadMessages() {
  try {
    const data = await api('/conversations/unread-count');
    const count = Number(data.count) || 0;
    const badge = $('#nav-msg-badge');
    const headerBadge = $('#nav-header-msg-badge');
    const mobBadge = $('#mob-msg-badge');
    const bottomBadge = $('#mbb-msg-badge');
    if (badge) { badge.textContent = count > 9 ? '9+' : count; badge.style.display = count > 0 ? 'inline' : 'none'; }
    if (headerBadge) { headerBadge.textContent = count > 9 ? '9+' : count; headerBadge.style.display = count > 0 ? 'grid' : 'none'; }
    if (mobBadge) { mobBadge.textContent = count > 9 ? '9+' : count; mobBadge.style.display = count > 0 ? 'inline' : 'none'; }
    if (bottomBadge) { bottomBadge.textContent = count > 99 ? '99+' : count; bottomBadge.style.display = count > 0 ? 'block' : 'none'; }
    ['#nav-msg-badge', '#nav-header-msg-badge', '#mob-msg-badge', '#mbb-msg-badge'].forEach(selector => {
      const element = $(selector);
      if (element) element.setAttribute('aria-label', count ? `${count} kişiden okunmamış mesaj var` : 'Okunmamış mesaj yok');
    });
  } catch {}
}

function redirectForAppUpdate(version) {
  if (!version) return false;
  const htmlVersion = document.querySelector('meta[name="cigcig-app-version"]')?.content || '';
  if (htmlVersion === version) {
    const currentUrl = new URL(location.href);
    if (currentUrl.searchParams.has('__cigcig_build')) {
      currentUrl.searchParams.delete('__cigcig_build');
      history.replaceState(history.state, '', currentUrl);
    }
    return false;
  }
  const currentUrl = new URL(location.href);
  if (currentUrl.searchParams.get('__cigcig_build') === version) return false;
  currentUrl.searchParams.set('__cigcig_build', version);
  location.replace(currentUrl.href);
  return true;
}

async function checkForAppUpdate() {
  const response = await fetch('/api/app-version', { cache: 'no-store', headers: { 'Cache-Control': 'no-cache' } });
  if (!response.ok) throw new Error(`Sürüm kontrolü başarısız (${response.status}).`);
  const result = await response.json();
  return redirectForAppUpdate(result.version);
}

function startAppVersionPolling() {
  if (appVersionPollTimer) clearInterval(appVersionPollTimer);
  appVersionPollTimer = setInterval(() => {
    checkForAppUpdate().catch(error => console.warn('Uygulama güncellemesi kontrol edilemedi:', error.message));
  }, 120000);
}

async function init() {
  $('#new-dropdown')?.classList.add('hidden');
  closeMobileCreateMenu();
  const authPromise = initAuth();
  const settingsController = new AbortController();
  const settingsTimeout = setTimeout(() => settingsController.abort(), 8000);
  const settingsPromise = fetch('/api/public-settings', { signal: settingsController.signal, cache: 'no-store', headers: { 'Cache-Control': 'no-cache' } });
  await authPromise;
  resumePendingVideoUpload();
  updateNavUI();
  loadAnnouncements();
  const currentPath = location.pathname + location.search;
  const canRenderBeforeSettings = Boolean(currentUser) || isPublicGuestRoute(location.pathname);
  if (canRenderBeforeSettings) {
    renderRoute(currentPath);
    window.hideMobileSplash?.();
  }
  try {
    const response = await settingsPromise;
    if (!response.ok) throw new Error(`Genel ayarlar yüklenemedi (${response.status}).`);
    const ps = await response.json();
    if (redirectForAppUpdate(ps.asset_version)) return;
    window.CigCigTheme?.configure({ ...ps, device_theme_enabled: '0' });
    document.body.classList.toggle('beta-mode-enabled', ps.beta_mode_enabled !== '0');
    siteName = ps.site_name && ps.site_name.toLowerCase() !== 'demlik' ? ps.site_name : 'CigCig';
    loginRequiredEnabled = ps.first_visit_auth === '1';
    const configuredPhotoClip = Number(ps.photo_song_clip_seconds);
    if (Number.isInteger(configuredPhotoClip) && configuredPhotoClip >= 1 && configuredPhotoClip <= 300) {
      photoSongClipSeconds = configuredPhotoClip;
    }
    if (ps.light_primary_color) document.documentElement.style.setProperty('--light-accent', ps.light_primary_color);
    if (ps.light_background_color) document.documentElement.style.setProperty('--light-bg', ps.light_background_color);
    window.otherSongsEnabled = ps.other_songs_enabled !== '0';
    window.founderUsername = ps.founder_username || '';
    window.founderColor = /^#[0-9a-f]{6}$/i.test(ps.founder_color || '') ? ps.founder_color : '#e11d48';
    // Kitap arka plan rengi CSS değişkeni olarak ayarla
    if (ps.book_bg_color) {
      document.documentElement.style.setProperty('--book-bg', ps.book_bg_color);
      // Açık renk için koyu metin, koyu renk için açık metin
      const hex = ps.book_bg_color.replace('#','');
      const r = parseInt(hex.slice(0,2),16), g = parseInt(hex.slice(2,4),16), b = parseInt(hex.slice(4,6),16);
      const luminance = (0.299*r + 0.587*g + 0.114*b) / 255;
      document.documentElement.style.setProperty('--book-text', luminance > 0.5 ? '#2c1a0e' : '#f5f0e8');
    }
    const bookFontFamilies = {
      Georgia: "'Georgia', serif",
      Palatino: "'Palatino Linotype', 'Book Antiqua', serif",
      Literata: "'Literata', Georgia, serif",
      Merriweather: "'Merriweather', Georgia, serif"
    };
    document.documentElement.style.setProperty('--book-reader-font', bookFontFamilies[ps.book_reader_font] || bookFontFamilies.Georgia);
    const brandSpan = document.querySelector('.nav-brand .site-wordmark');
    if (brandSpan) brandSpan.textContent = siteName;
    const footer = document.getElementById('site-footer');
    if (footer) {
      footer.textContent = ps.footer_copyright_text || '© 2026 İsmail D. Tüm hakları saklıdır.';
    }
  } catch (error) {
    console.warn('Genel ayarlar yüklenemedi; varsayılan ayarlarla devam ediliyor:', error.message);
  } finally {
    clearTimeout(settingsTimeout);
  }
  startAppVersionPolling();
  if (!canRenderBeforeSettings) {
    renderRoute(location.pathname + location.search);
    window.hideMobileSplash?.();
  }
  try {
    const journalists = await api('/journalists');
    journalistDirectory.clear();
    journalists.forEach(journalist => {
      journalistDirectory.set(String(journalist.username || '').toLocaleLowerCase('tr-TR'), journalist);
    });
  } catch (error) {
    console.warn('Gazeteci listesi yüklenemedi:', error.message);
  }
  updateNavUI();
  if (currentUser) {
    checkUnreadMessages();
    setInterval(() => { if (currentUser) checkUnreadMessages(); }, 15000);
    loadNotifCount();
    setInterval(() => { if (currentUser) loadNotifCount(); }, 30000);
  }
}

async function loadAnnouncements() {
  try {
    const rows = await fetch('/api/announcements').then(r => r.json());
    const container = document.getElementById('announcements-container');
    if (!container) return;
    container.innerHTML = '';
    rows.forEach(ann => {
      const div = document.createElement('div');
      div.className = `announcement-banner ann-${ann.position || 'top'} ann-size-${ann.size || 'normal'}`;
      div.style.cssText = `background:${ann.bg_color};color:${ann.text_color};border-color:${ann.border_color};`;
      div.innerHTML = `
        <div class="ann-inner">
          <div class="ann-text"><strong>${escHtml(ann.title)}</strong> <span>${escHtml(ann.content)}</span></div>
          <button class="ann-close" onclick="this.closest('.announcement-banner').remove()" aria-label="Kapat"><i class="fas fa-times"></i></button>
        </div>`;
      container.appendChild(div);
    });
  } catch {}
}

function installHoverDescriptions() {
  const iconDescriptions = {
    'fa-play': 'Çal',
    'fa-pause': 'Duraklat',
    'fa-random': 'Karıştır',
    'fa-shuffle': 'Karışık çal',
    'fa-redo-alt': 'Şarkıyı tekrarla',
    'fa-repeat': 'Şarkıyı tekrarla',
    'fa-step-backward': 'Önceki şarkı',
    'fa-step-forward': 'Sonraki şarkı',
    'fa-volume-up': 'Ses düzeyi',
    'fa-volume-high': 'Ses düzeyi',
    'fa-volume-off': 'Sesi aç',
    'fa-volume-xmark': 'Sesi kapat',
    'fa-plus': 'Ekle',
    'fa-times': 'Kapat',
    'fa-xmark': 'Kapat',
    'fa-trash': 'Sil',
    'fa-trash-alt': 'Sil',
    'fa-edit': 'Düzenle',
    'fa-pen': 'Düzenle',
    'fa-search': 'Ara',
    'fa-magnifying-glass': 'Ara',
    'fa-heart': 'Beğen',
    'fa-share': 'Paylaş',
    'fa-share-alt': 'Paylaş',
    'fa-comment': 'Yorumlar',
    'fa-ellipsis-h': 'Diğer seçenekler',
    'fa-ellipsis-v': 'Diğer seçenekler',
    'fa-ellipsis': 'Diğer seçenekler',
    'fa-lock': 'Kilitle',
    'fa-unlock': 'Kilidi aç',
    'fa-bell': 'Bildirimler',
    'fa-bell-slash': 'Sessize al',
    'fa-link': 'Linki kopyala',
    'fa-download': 'İndir',
    'fa-upload': 'Yükle',
    'fa-camera': 'Fotoğraf',
    'fa-arrow-left': 'Geri',
    'fa-chevron-left': 'Geri',
    'fa-arrow-right': 'İleri',
    'fa-chevron-right': 'İleri'
  };
  const selector = 'button, a[href], [role="button"], input[type="button"], input[type="submit"], input[type="range"], select';
  const describe = element => {
    if (element.hasAttribute('title')) return;
    const explicit = element.getAttribute('aria-label') || element.dataset.tooltip || element.getAttribute('placeholder');
    const text = (element.innerText || element.value || '').replace(/\s+/g, ' ').trim();
    const icon = element.querySelector('i, svg');
    const iconDescription = icon && [...icon.classList].map(name => iconDescriptions[name]).find(Boolean);
    const label = explicit || (text.length > 1 && text.length <= 80 ? text : '') || iconDescription;
    if (label) element.setAttribute('title', label);
  };
  const scan = node => {
    if (!(node instanceof Element)) return;
    if (node.matches(selector)) describe(node);
    node.querySelectorAll(selector).forEach(describe);
  };
  scan(document.body);
  new MutationObserver(records => {
    records.forEach(record => record.addedNodes.forEach(scan));
  }).observe(document.body, { childList: true, subtree: true });
}

function installSiteImageUrls() {
  const rewriteImage = image => {
    const rawSource = image.getAttribute('src');
    if (!rawSource) return;
    const proxiedSource = siteImageUrl(rawSource);
    if (proxiedSource !== rawSource) {
      image.setAttribute('src', proxiedSource);
      const parentLink = image.closest('a[href]');
      if (parentLink) {
        const proxiedHref = siteImageUrl(parentLink.getAttribute('href'));
        if (proxiedHref !== parentLink.getAttribute('href')) parentLink.setAttribute('href', proxiedHref);
      }
    }
  };
  const scan = node => {
    if (!(node instanceof Element)) return;
    if (node.matches('img')) rewriteImage(node);
    node.querySelectorAll('img').forEach(rewriteImage);
    if (node.matches('a[href]')) {
      const proxiedHref = siteImageUrl(node.getAttribute('href'));
      if (proxiedHref !== node.getAttribute('href')) node.setAttribute('href', proxiedHref);
    }
  };
  scan(document.body);
  new MutationObserver(records => {
    records.forEach(record => {
      if (record.type === 'attributes') {
        if (record.target instanceof HTMLImageElement) rewriteImage(record.target);
        else scan(record.target);
      } else {
        record.addedNodes.forEach(scan);
      }
    });
  }).observe(document.body, { childList: true, subtree: true, attributes: true, attributeFilter: ['src', 'href'] });
}

installHoverDescriptions();
installSiteImageUrls();

